from functools import update_wrapper

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorator(func):
        cache = {}
        def wrapper(*args, **kwargs):
            # Generate a unique key for the function arguments
            if not typed:
                key = args + tuple(kwargs.items())
            else:
                key = (args, frozenset(kwargs.items()))
            # Check if the key is already in the cache
            try:
                value, last_update = cache[key]
                if timer() - last_update > ttl:
                    raise KeyError
            except KeyError:
                # Key not in cache or too old, call the function
                value = func(*args, **kwargs)
                # Save the result in the cache
                cache[key] = (value, timer())
                # Check if we exceeded the max size and need to purge
                if len(cache) > maxsize:
                    # Iterate over all keys and values and delete the
                    # oldest entries.
                    current_time = timer()
                    for key, (value, last_update) in list(cache.items()):
                        if current_time - last_update > ttl:
                            del cache[key]
            return value
        # Copy the function's documentation and other attributes
        update_wrapper(wrapper, func)
        # Return the decorated function
        return wrapper
    return decorator
