            "authors": [author.text.strip() for author in authors] if authors else None,
            "date": date.text.strip() if date else None
        }

    with ZipFile(zip_path) as zip:
        files = [file for file in zip.infolist() if file.filename.lower().endswith('.xml')]

        data = {}
