def verifyObject(iface, candidate, tentative=False):
    # ensure the candidate claims to provide the interface
    if not tentative and not iface.providedBy(candidate):
        raise Invalid(f"{candidate} does not declare that it provides {iface}")

    # gather all the declared methods and attributes for the interface
    interface_methods = set(iface.names())
    interface_attributes = set()
    for name in interface_methods:
        method = getattr(iface, name)
        if isinstance(method, Attribute):
            interface_attributes.add(name)
            interface_methods.remove(name)

    # check that all methods are implemented correctly
    for method_name in interface_methods:
        candidate_method = getattr(candidate, method_name, None)
        if not callable(candidate_method):
            raise Invalid(
                f"{candidate} does not define a method {method_name}() required by {iface}"
            )
        else:
            candidate_signature = inspect.signature(candidate_method)
            interface_signature = inspect.signature(method)
            if candidate_signature != interface_signature:
                raise Invalid(
                    f"{candidate}'s definition of {method_name}() has an incorrect signature. Expected {interface_signature}, got {candidate_signature}"
                )

    # check that all attributes are defined correctly
    for attribute_name in interface_attributes:
        candidate_attribute = getattr(candidate, attribute_name, None)
        if not isinstance(candidate_attribute, Descriptor):
            raise Invalid(
                f"{candidate} does not define an attribute {attribute_name} required by {iface}"
            )

    return True

