        data = json.loads(document)
        if not isinstance(data, dict):
            raise ValueError("Invalid Diaspora webfinger: expected dict, got {}".format(type(data)))

        links = data.get("links", [])
        if not isinstance(links, list):
            raise ValueError("Invalid Diaspora webfinger: expected list for 'links', got {}".format(type(links)))

        for link in links:
            if not isinstance(link, dict):
                raise ValueError(
                    "Invalid Diaspora webfinger: expected dict for link, got {}".format(type(link)))

        return data

    except ValueError as ve:
        raise ve

    except:
        try:
            from xml.etree import ElementTree

            data = ElementTree.fromstring(document)
            links = data.findall("{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link")
            for link in links:
                if not isinstance(link, ElementTree.Element):
                    raise ValueError(
                        "Invalid XRD: expected ElementTree.Element for link, got {}".format(type(link)))

                rel = link.attrib.get("rel")
                if not isinstance(rel, str):
                    raise ValueError(
                        "Invalid XRD: expected string for 'rel' attribute, got {}".format(type(rel)))

                href = link.attrib.get("href")
                if not isinstance(href, str):
                    raise ValueError(
                        "Invalid XRD: expected string for 'href' attribute, got {}".format(type(href)))

                template = link.find("{http://docs.oasis-open.org/ns/xri/xrd-1.0}Template")
                if template is not None:
                    if not isinstance(template, ElementTree.Element):
                        raise ValueError(
                            "Invalid XRD: expected ElementTree.Element for template, got {}".format(type(template)))

                    content = template.find("{http://docs.oasis-open.org/ns/xri/xrd-1.0}Content")
                    if content is not None:
                        values = {}
                        for attr in content.attrib:
                            values[attr] = escape(content.attrib[attr]).replace("'", '"')

                        return {"data": {"rel": rel, "href": href, "template": values}}

        except ValueError as ve:
            raise ve

        except:
            raise ValueError("Invalid Diaspora webfinger: expected JSON or XRD, got {}".format(document))

