    """
    complex_type = get_complex_type(type_name)
    if not complex_type:
        raise ValueError(f"Invalid complex type: {type_name}")
    if not spec_option:
        raise ValueError("Missing option specifications")
    if not subcommand:
        raise ValueError("Missing subcommand")
    if not option_name:
        raise ValueError("Missing option name")
    if not isinstance(subcommand, str):
        raise ValueError("Subcommand must be a string")
    if not isinstance(type_name, str):
        raise ValueError("Type name must be a string")
    if not isinstance(option_name, str):
        raise ValueError("Option name must be a string")
    if not isinstance(spec_option, (dict, list)):
        raise ValueError("Option specifications must be a dictionary or a list")
    if isinstance(spec_option, list):
        spec_option = {opt: None for opt in spec_option}
    return complex_type(subcommand, type_name, option_name, spec_option)

